('Kelewele (Spicy Fried Plantains)', 'Ghana', 'Sweet and spicy fried plantain cubes seasoned with ginger, cayenne, and aromatic spices. Popular West African street food snack.', 'Easy', 15, 15, 4, ARRAY['snack', 'vegan', 'street food'], '[{"name": "Ripe plantains", "amount": "4"}, {"name": "Fresh ginger", "amount": "2 tbsp grated"}, {"name": "Cayenne pepper", "amount": "1 tsp"}, {"name": "Ground cloves", "amount": "1/4 tsp"}, {"name": "Salt", "amount": "to taste"}, {"name": "Vegetable oil", "amount": "for frying"}]'::jsonb, '[{"step": 1, "instruction": "Peel and cube plantains"}, {"step": 2, "instruction": "Mix with spices, marinate 10 minutes"}, {"step": 3, "instruction": "Heat oil to 350°F"}, {"step": 4, "instruction": "Fry until golden brown"}, {"step": 5, "instruction": "Drain and serve hot"}]'::jsonb, true, 'kelewele-spicy-plantains', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

('Red Red (Bean Stew)', 'Ghana', 'Rich black-eyed pea stew in palm oil with tomatoes. Served with fried plantains.', 'Medium', 20, 60, 6, ARRAY['main course', 'vegan', 'beans'], '[{"name": "Black-eyed peas", "amount": "2 cups"}, {"name": "Palm oil", "amount": "1/2 cup"}, {"name": "Tomatoes", "amount": "4 large"}, {"name": "Onions", "amount": "2 large"}, {"name": "Ginger", "amount": "2 tbsp"}, {"name": "Scotch bonnet", "amount": "1-2"}]'::jsonb, '[{"step": 1, "instruction": "Soak and cook beans until tender"}, {"step": 2, "instruction": "Heat palm oil, fry onions"}, {"step": 3, "instruction": "Add blended tomatoes and pepper"}, {"step": 4, "instruction": "Cook until oil separates"}, {"step": 5, "instruction": "Add beans, simmer 30 minutes"}]'::jsonb, true, 'red-red-bean-stew', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

('Kilishi (Spiced Jerky)', 'Nigeria', 'Thinly sliced beef in spicy peanut paste, sun-dried. Northern Nigerian protein snack.', 'Hard', 30, 180, 8, ARRAY['snack', 'protein', 'preserved'], '[{"name": "Beef", "amount": "2 lbs thin slices"}, {"name": "Groundnut paste", "amount": "1/2 cup"}, {"name": "Ginger", "amount": "2 tbsp"}, {"name": "Cayenne", "amount": "2 tbsp"}, {"name": "Garlic powder", "amount": "1 tbsp"}]'::jsonb, '[{"step": 1, "instruction": "Pound beef very thin"}, {"step": 2, "instruction": "Mix spice paste"}, {"step": 3, "instruction": "Coat meat thoroughly"}, {"step": 4, "instruction": "Dry in sun 6-8 hours"}, {"step": 5, "instruction": "Grill briefly before serving"}]'::jsonb, true, 'kilishi-spiced-jerky', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

('Bissap Juice', 'Senegal', 'Refreshing hibiscus drink with mint and orange blossom water.', 'Easy', 10, 30, 8, ARRAY['beverage', 'vegan', 'refreshing'], '[{"name": "Dried hibiscus", "amount": "2 cups"}, {"name": "Water", "amount": "8 cups"}, {"name": "Sugar", "amount": "1-2 cups"}, {"name": "Mint", "amount": "1/2 cup"}, {"name": "Orange blossom water", "amount": "2 tbsp"}]'::jsonb, '[{"step": 1, "instruction": "Rinse hibiscus flowers"}, {"step": 2, "instruction": "Boil with mint 20 minutes"}, {"step": 3, "instruction": "Strain liquid"}, {"step": 4, "instruction": "Add sugar and orange blossom water"}, {"step": 5, "instruction": "Chill and serve over ice"}]'::jsonb, true, 'bissap-juice', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

('Cachupa', 'Cape Verde', 'Slow-cooked corn and bean stew with vegetables and meat. Cape Verdean national dish.', 'Medium', 30, 120, 8, ARRAY['main course', 'stew', 'hearty'], '[{"name": "Hominy corn", "amount": "2 cups"}, {"name": "Lima beans", "amount": "1 cup"}, {"name": "Cabbage", "amount": "1/2 head"}, {"name": "Sweet potato", "amount": "2 medium"}, {"name": "Chorizo", "amount": "1 lb"}]'::jsonb, '[{"step": 1, "instruction": "Soak corn and beans overnight"}, {"step": 2, "instruction": "Cook corn 1 hour"}, {"step": 3, "instruction": "Add beans, cook 30 minutes"}, {"step": 4, "instruction": "Add meat and root vegetables"}, {"step": 5, "instruction": "Add cabbage last 15 minutes"}]'::jsonb, true, 'cachupa', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

('Tuo Zaafi with Ayoyo Soup', 'Ghana', 'Northern Ghanaian corn dough balls with jute leaf soup.', 'Medium', 20, 40, 4, ARRAY['main course', 'soup', 'traditional'], '[{"name": "Corn dough", "amount": "3 cups"}, {"name": "Jute leaves", "amount": "4 cups"}, {"name": "Smoked fish", "amount": "1 cup"}, {"name": "Palm oil", "amount": "1/4 cup"}, {"name": "Dawadawa", "amount": "2 tbsp"}]'::jsonb, '[{"step": 1, "instruction": "Boil water, add corn dough gradually"}, {"step": 2, "instruction": "Stir continuously 20 minutes"}, {"step": 3, "instruction": "Form into balls"}, {"step": 4, "instruction": "Make soup with palm oil, fish, leaves"}, {"step": 5, "instruction": "Simmer soup 15 minutes"}]'::jsonb, true, 'tuo-zaafi-ayoyo-soup', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

('Ewa Agoyin', 'Nigeria', 'Soft mashed beans with spicy palm oil sauce. Lagos street food favorite.', 'Easy', 15, 60, 4, ARRAY['main course', 'vegan', 'street food'], '[{"name": "Honey beans", "amount": "2 cups"}, {"name": "Palm oil", "amount": "1 cup"}, {"name": "Scotch bonnet", "amount": "5-6"}, {"name": "Onions", "amount": "3 large"}]'::jsonb, '[{"step": 1, "instruction": "Cook beans until very soft"}, {"step": 2, "instruction": "Mash beans roughly"}, {"step": 3, "instruction": "Blend peppers with onions"}, {"step": 4, "instruction": "Fry onions in palm oil until dark"}, {"step": 5, "instruction": "Add pepper blend, cook 20 minutes"}]'::jsonb, true, 'ewa-agoyin', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

