('Bambara Groundnut Soup', 'Mali', 'Creamy soup from indigenous African groundnuts. Nutritious and protein-rich.', 'Medium', 20, 50, 6, ARRAY['soup', 'vegan', 'protein'], '[{"name": "Bambara nuts", "amount": "2 cups"}, {"name": "Tomatoes", "amount": "4 medium"}, {"name": "Palm oil", "amount": "1/4 cup"}, {"name": "Spinach", "amount": "3 cups"}]'::jsonb, '[{"step": 1, "instruction": "Soak nuts 4 hours"}, {"step": 2, "instruction": "Cook until soft, blend half"}, {"step": 3, "instruction": "Fry onions and tomatoes"}, {"step": 4, "instruction": "Add nuts and water"}, {"step": 5, "instruction": "Add spinach, simmer 20 minutes"}]'::jsonb, true, 'bambara-groundnut-soup', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

('Alloco', 'Ivory Coast', 'Fried sweet plantains with spicy pepper sauce.', 'Easy', 10, 15, 4, ARRAY['snack', 'side dish', 'vegan'], '[{"name": "Ripe plantains", "amount": "4"}, {"name": "Vegetable oil", "amount": "for frying"}, {"name": "Onions", "amount": "2 large"}, {"name": "Tomatoes", "amount": "3 medium"}, {"name": "Habanero", "amount": "2-3"}]'::jsonb, '[{"step": 1, "instruction": "Slice plantains diagonally"}, {"step": 2, "instruction": "Fry until golden"}, {"step": 3, "instruction": "Blend tomatoes, peppers, onions"}, {"step": 4, "instruction": "Cook sauce until thick"}, {"step": 5, "instruction": "Serve alloco with sauce"}]'::jsonb, true, 'alloco', (SELECT id FROM regions WHERE name = 'West Africa' LIMIT 1)),

